#!/usr/bin/env node
/**
 * Fetches Shutterstock's LDNOOBW English wordlist and emits
 * src/features/nsfw/wordlist.generated.ts.
 *
 * Run with: pnpm gen:wordlist
 *
 * The generated file is committed so the PWA stays fully offline.
 */
import { writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

const SOURCE_URL =
  'https://raw.githubusercontent.com/LDNOOBW/List-of-Dirty-Naughty-Obscene-and-Otherwise-Bad-Words/master/en';

const __dirname = dirname(fileURLToPath(import.meta.url));
const OUT_PATH = resolve(
  __dirname,
  '../src/features/nsfw/wordlist.generated.ts',
);

const fetchList = async () => {
  const res = await fetch(SOURCE_URL);
  if (!res.ok) {
    throw new Error(`Failed to fetch ${SOURCE_URL}: ${res.status}`);
  }
  return res.text();
};

const sanitize = (raw) => {
  const allowed = /^[a-z][a-z0-9 \-]*$/;
  const seen = new Set();
  const out = [];
  for (const line of raw.split('\n')) {
    const trimmed = line.trim().toLowerCase();
    if (!trimmed) continue;
    if (!allowed.test(trimmed)) continue;
    if (seen.has(trimmed)) continue;
    seen.add(trimmed);
    out.push(trimmed);
  }
  out.sort();
  return out;
};

const emit = (words) => {
  const items = words.map((w) => `  ${JSON.stringify(w)},`).join('\n');
  return `// AUTO-GENERATED by scripts/generate-wordlist.mjs. Do not edit by hand.
// Source: Shutterstock LDNOOBW English list (MIT).
// Run \`pnpm gen:wordlist\` to refresh.

export const ldnoobwEnglish: readonly string[] = [
${items}
];
`;
};

const main = async () => {
  console.log(`Fetching ${SOURCE_URL}...`);
  const raw = await fetchList();
  const words = sanitize(raw);
  console.log(`Sanitized ${words.length} entries.`);
  await writeFile(OUT_PATH, emit(words), 'utf8');
  console.log(`Wrote ${OUT_PATH}`);
};

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
